const input = $input.first().json || {};

function nowIso() {
  return new Date().toISOString();
}

function normalizeString(value) {
  if (value === undefined || value === null) return "";
  return String(value).trim();
}

function normalizeExtension(file) {
  const explicit = normalizeString(file.extension).toLowerCase().replace(/^\./, "");
  if (explicit) return explicit;

  const filename = normalizeString(file.filename);
  const parts = filename.split(".");
  if (parts.length > 1) return parts.pop().toLowerCase();

  return "";
}

function normalizeList(list) {
  return Array.isArray(list)
    ? list.map(item => normalizeString(item).toLowerCase().replace(/^\./, "")).filter(Boolean)
    : [];
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        success: false,
        component_id: "C4-T",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        document_processing: null,
        c4b_handoff: null,
        ocr_handoff: null,
        manual_review_handoff: null,
        source_result: input.input || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};

if (source.success !== true) {
  return fail({
    code: "UPSTREAM_ACTION_FAILED",
    message: "C4-T will not process document when upstream action failed.",
    details: [
      {
        upstream_component: source.component_id || null,
        upstream_error: source.error || null
      }
    ]
  });
}

if (source.next_action !== "process_document") {
  return fail({
    code: "DOCUMENT_PROCESSING_NOT_REQUESTED",
    message: "source.next_action is not process_document.",
    details: [{ next_action: source.next_action || null }]
  });
}

if (!source.file || typeof source.file !== "object") {
  return fail({
    code: "MISSING_FILE_OBJECT",
    message: "input.file is required."
  });
}

if (!source.file.filename) {
  return fail({
    code: "MISSING_FILENAME",
    message: "input.file.filename is required."
  });
}

const file = source.file;
const extension = normalizeExtension(file);
const mimeType = normalizeString(file.mime_type).toLowerCase();
const sizeBytes = Number(file.size_bytes || 0);

if (!extension) {
  return fail({
    code: "MISSING_FILE_EXTENSION",
    message: "File extension could not be determined."
  });
}

const supportedExtensions = normalizeList(config.supported_extensions);
const ocrExtensions = normalizeList(config.ocr_extensions);
const maxFileSizeBytes = Number(config.max_file_size_bytes || 0);

if (supportedExtensions.length > 0 && !supportedExtensions.includes(extension)) {
  return fail({
    code: "UNSUPPORTED_FILE_EXTENSION",
    message: "File extension is not supported by C4-T.",
    details: [
      {
        filename: file.filename,
        extension,
        supported_extensions: supportedExtensions
      }
    ]
  });
}

if (maxFileSizeBytes > 0 && sizeBytes > maxFileSizeBytes) {
  return fail({
    code: "FILE_TOO_LARGE",
    message: "File exceeds configured max_file_size_bytes.",
    details: [
      {
        filename: file.filename,
        size_bytes: sizeBytes,
        max_file_size_bytes: maxFileSizeBytes
      }
    ]
  });
}

const documentInput = source.document || {};
const extractedText = normalizeString(documentInput.extracted_text);
const textAvailable = documentInput.text_available === true && extractedText.length > 0;
const pageCount = Number(documentInput.page_count || 1);
const ocrRequiredWhenNoText = config.ocr_required_when_no_text === true;
const shouldRunOcr = !textAvailable && ocrRequiredWhenNoText && ocrExtensions.includes(extension);

const documentProcessingBase = {
  file_id: file.file_id || null,
  filename: file.filename,
  extension,
  mime_type: mimeType || null,
  size_bytes: sizeBytes,
  source_url: file.source_url || null,
  storage_provider: file.storage_provider || null,
  file_category: source.file_route?.file_category || null,
  page_count: pageCount,
  text_available: textAvailable,
  extracted_text: textAvailable ? extractedText : null,
  source_text_method: documentInput.source_text_method || null,
  document_goal: config.document_goal || null,
  processed_at: nowIso()
};

if (textAvailable) {
  const extractionTarget = config.extraction_target || {};
  const c4bHandoff = {
    next_component: extractionTarget.next_component || "C4-B",
    input: {
      success: true,
      component_id: "C4-T",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: "document_text_ready",
      payload: {
        raw_text: extractedText,
        source: file.filename,
        file_id: file.file_id || null,
        filename: file.filename,
        document_goal: config.document_goal || null
      },
      document_processing: {
        ...documentProcessingBase,
        route_status: "text_ready",
        route_reason: "Document text is already available."
      },
      metadata: {
        source_component: source.component_id || null,
        original_event_type: source.event_type || null,
        origin: source.metadata?.origin || null,
        environment: source.metadata?.environment || null,
        processed_at: documentProcessingBase.processed_at
      },
      error: null,
      next_action: extractionTarget.next_action || "extract_fields"
    },
    config: {
      extraction_mode: "rules_plus_ai",
      extraction_goal: extractionTarget.extraction_goal || "Extract structured fields from document text.",
      client_ai_profile: config.client_ai_profile || {
        client_profile: {
          client_name: "Default Client"
        },
        extraction_rules: {
          required_fields: [],
          optional_fields: [],
          missing_required_field_action: "manual_review",
          allow_inference: false,
          never_infer_fields: [],
          low_confidence_action: "manual_review",
          manual_review_confidence_threshold: 0.75
        }
      },
      llm: config.llm || {
        provider: "groq",
        endpoint: "https://api.groq.com/openai/v1/chat/completions",
        model: "llama-3.3-70b-versatile",
        temperature: 0.1,
        max_tokens: 800
      },
      default_next_action: "validate_payload"
    }
  };

  return [
    {
      json: {
        success: true,
        component_id: "C4-T",
        component_version: "v1",
        event_id: source.event_id || null,
        event_type: source.event_type || null,
        document_processing: {
          ...documentProcessingBase,
          route_status: "text_ready",
          route_reason: "Document text is already available."
        },
        c4b_handoff: c4bHandoff,
        ocr_handoff: null,
        manual_review_handoff: null,
        source_result: source,
        error: null,
        next_action: config.default_next_action || "extract_fields"
      }
    }
  ];
}

if (shouldRunOcr) {
  const ocrTarget = config.ocr_target || {};

  const ocrHandoff = {
    next_component: ocrTarget.next_component || "ocr_adapter",
    input: {
      success: true,
      component_id: "C4-T",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: "ocr_request",
      file: {
        ...file,
        extension,
        mime_type: mimeType || file.mime_type || null
      },
      document_processing: {
        ...documentProcessingBase,
        route_status: "ocr_required",
        route_reason: "No usable text is available and OCR is required/configured."
      },
      source_result: source,
      error: null,
      next_action: ocrTarget.next_action || "run_ocr"
    },
    config: {
      ocr_provider: config.ocr_provider || "external_ocr_adapter",
      output_next_component: config.extraction_target?.next_component || "C4-B",
      output_next_action: config.extraction_target?.next_action || "extract_fields",
      extraction_goal: config.extraction_target?.extraction_goal || "Extract structured fields from OCR text.",
      default_next_action: "extract_fields"
    }
  };

  return [
    {
      json: {
        success: true,
        component_id: "C4-T",
        component_version: "v1",
        event_id: source.event_id || null,
        event_type: source.event_type || null,
        document_processing: {
          ...documentProcessingBase,
          route_status: "ocr_required",
          route_reason: "No usable text is available and OCR is required/configured."
        },
        c4b_handoff: null,
        ocr_handoff: ocrHandoff,
        manual_review_handoff: null,
        source_result: source,
        error: null,
        next_action: config.default_next_action || "run_ocr"
      }
    }
  ];
}

const manualReviewHandoff = {
  next_component: "C5-E",
  input: {
    success: true,
    component_id: "C4-T",
    component_version: "v1",
    event_id: source.event_id || null,
    event_type: "document_processing_review",
    document_processing: {
      ...documentProcessingBase,
      route_status: "manual_review_required",
      route_reason: "No text available and OCR route is not configured for this file."
    },
    source_result: source,
    error: null,
    next_action: "manual_review"
  },
  config: {
    queue_type: "document_processing_review",
    review_reason: "Document could not be processed automatically.",
    reviewer_email: config.reviewer_email || "shwetabh.singh@lexnovahq.com",
    owner: "ops",
    priority: "normal",
    allowed_actions: ["run_ocr_manually", "extract_text_manually", "reject_file", "request_new_file"],
    default_next_action: "notify_reviewer"
  }
};

return [
  {
    json: {
      success: true,
      component_id: "C4-T",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: source.event_type || null,
      document_processing: {
        ...documentProcessingBase,
        route_status: "manual_review_required",
        route_reason: "No text available and OCR route is not configured for this file."
      },
      c4b_handoff: null,
      ocr_handoff: null,
      manual_review_handoff: manualReviewHandoff,
      source_result: source,
      error: null,
      next_action: "manual_review"
    }
  }
];
